-- students: one row per student, used by the Student CRUD (/api/students).
--   * id          uuid, generated by the database (gen_random_uuid(), built into Postgres 13+).
--   * name        max 100 characters; the app trims spaces before saving.
--   * reg_number  exactly 8 digits, unique across all students.
--   * dob         date of birth as timestamptz (UTC midnight), so the API returns "2005-08-15T00:00:00.000Z".
-- Must match src/frameworks/postgres/model/student.ts.
-- Apply MANUALLY, e.g.:  node apply_sql.js migrations/20261111012603_create_students.sql .env.dev
-- Rollback:              drop table students;
--                        delete from "__EFMigrationsHistory" where "MigrationId" = '20261111012603_create_students';

begin;

create table students (
  id          uuid         not null default gen_random_uuid(),
  name        varchar(100) not null,
  reg_number  integer      not null,
  dob         timestamptz  not null,
  created_at  timestamptz  not null default now(),
  updated_at  timestamptz  not null default now(),
  constraint pk_students primary key (id),
  constraint uq_students_reg_number unique (reg_number),
  constraint ck_students_reg_number_8_digits check (reg_number between 10000000 and 99999999)
);

-- Record this migration in the history table (same layout as the company projects), so it shows as applied.
create table if not exists "__EFMigrationsHistory" (
  "MigrationId"    varchar(150) not null primary key,
  "ProductVersion" varchar(32)  not null
);
insert into "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
select '20261111012603_create_students',
       coalesce((select "ProductVersion" from "__EFMigrationsHistory" order by "MigrationId" desc limit 1), '8.0.0')
on conflict ("MigrationId") do nothing;

commit;
